pub mod wifi_mac_interface_address {
    pub use oer_espressif_ieee80211_pac::wifi_mac_interface_address::*;

    /// The block's base address.
    pub const BASE: usize = 0x2010405c;

    /// The block's device registers, as the PAC root claims them.
    pub type Claim = oer_mmio::Block<oer_mmio::Fixed<0x2010405c>, BlockWords>;

    /// The exclusive owner of the `WIFI_MAC_INTERFACE_ADDRESS` registers, at this chip's address
    /// unless placed in host memory.
    pub type WifiMacInterfaceAddress<P = oer_mmio::Fixed<0x2010405c>> =
        oer_espressif_ieee80211_pac::wifi_mac_interface_address::WifiMacInterfaceAddress<P>;
}

/// The ownership partitions of the typed register blocks.
pub mod peripheral_ownership {
    /// The eFuse controller's read words of the factory MAC and the chip revision, read once by the factory identity.
    pub struct EfusePeripherals {
        pub efuse: super::efuse::Efuse,
    }

    /// The device registers of [`EfusePeripherals`]'s blocks, which its platform
    /// handoff claims with one `oer_mmio::assume_owned`; the PAC root
    /// does not claim them.
    pub type EfusePeripheralsClaims = super::efuse::Claim;

    impl EfusePeripherals {
        /// Give each claimed block to its owner.
        #[inline]
        pub fn from_claims(claims: EfusePeripheralsClaims) -> Self {
            let efuse = claims;
            Self {
                efuse: super::efuse::Efuse::new(efuse),
            }
        }
    }

    /// The true random number generator and its clock and reset word, read by the entropy owner.
    pub struct EntropyPeripherals {
        pub trng: super::trng::Trng,
        pub lp_periclkrst_rng: super::lp_periclkrst_rng::LpPericlkrstRng,
    }

    /// The device registers of [`EntropyPeripherals`]'s blocks, which its platform
    /// handoff claims with one `oer_mmio::assume_owned`; the PAC root
    /// does not claim them.
    pub type EntropyPeripheralsClaims = (super::trng::Claim, super::lp_periclkrst_rng::Claim);

    impl EntropyPeripherals {
        /// Give each claimed block to its owner.
        #[inline]
        pub fn from_claims(claims: EntropyPeripheralsClaims) -> Self {
            let (trng, lp_periclkrst_rng) = claims;
            Self {
                trng: super::trng::Trng::new(trng),
                lp_periclkrst_rng: super::lp_periclkrst_rng::LpPericlkrstRng::new(
                    lp_periclkrst_rng,
                ),
            }
        }
    }

    /// The reset-cause words of both HP cores, read by the reset-cause owner.
    pub struct ResetCausePeripherals {
        pub lp_aon_reset_cause: super::lp_aon_reset_cause::LpAonResetCause,
    }

    /// The device registers of [`ResetCausePeripherals`]'s blocks, which its platform
    /// handoff claims with one `oer_mmio::assume_owned`; the PAC root
    /// does not claim them.
    pub type ResetCausePeripheralsClaims = super::lp_aon_reset_cause::Claim;

    impl ResetCausePeripherals {
        /// Give each claimed block to its owner.
        #[inline]
        pub fn from_claims(claims: ResetCausePeripheralsClaims) -> Self {
            let lp_aon_reset_cause = claims;
            Self {
                lp_aon_reset_cause: super::lp_aon_reset_cause::LpAonResetCause::new(
                    lp_aon_reset_cause,
                ),
            }
        }
    }

    /// The main watchdogs of both timer groups, timer group 1's clock and reset, and the RTC and super watchdogs, owned by the watchdog owners.
    pub struct WatchdogPeripherals {
        pub timg0_wdt: super::timg0_wdt::Timg0Wdt,
        pub timg1_wdt: super::timg1_wdt::Timg1Wdt,
        pub hp_sys_clkrst_timg1: super::hp_sys_clkrst_timg1::HpSysClkrstTimg1,
        pub lp_wdt: super::lp_wdt::LpWdt,
        pub lp_wdt_swd: super::lp_wdt_swd::LpWdtSwd,
    }

    /// The device registers of [`WatchdogPeripherals`]'s blocks, which its platform
    /// handoff claims with one `oer_mmio::assume_owned`; the PAC root
    /// does not claim them.
    pub type WatchdogPeripheralsClaims = (
        super::timg0_wdt::Claim,
        super::timg1_wdt::Claim,
        super::hp_sys_clkrst_timg1::Claim,
        super::lp_wdt::Claim,
        super::lp_wdt_swd::Claim,
    );

    impl WatchdogPeripherals {
        /// Give each claimed block to its owner.
        #[inline]
        pub fn from_claims(claims: WatchdogPeripheralsClaims) -> Self {
            let (timg0_wdt, timg1_wdt, hp_sys_clkrst_timg1, lp_wdt, lp_wdt_swd) = claims;
            Self {
                timg0_wdt: super::timg0_wdt::Timg0Wdt::new(timg0_wdt),
                timg1_wdt: super::timg1_wdt::Timg1Wdt::new(timg1_wdt),
                hp_sys_clkrst_timg1: super::hp_sys_clkrst_timg1::HpSysClkrstTimg1::new(
                    hp_sys_clkrst_timg1,
                ),
                lp_wdt: super::lp_wdt::LpWdt::new(lp_wdt),
                lp_wdt_swd: super::lp_wdt_swd::LpWdtSwd::new(lp_wdt_swd),
            }
        }
    }

    /// The system timer: the comparators the time driver programs and the shared counter latch every context reads. Claimed by the time driver's platform handoff.
    pub struct SystemTimerPeripherals {
        pub systimer: super::systimer::Systimer,
        pub systimer_counter: super::systimer_counter::SystimerCounter,
    }

    /// The device registers of [`SystemTimerPeripherals`]'s blocks, which its platform
    /// handoff claims with one `oer_mmio::assume_owned`; the PAC root
    /// does not claim them.
    pub type SystemTimerPeripheralsClaims =
        (super::systimer::Claim, super::systimer_counter::Claim);

    impl SystemTimerPeripherals {
        /// Give each claimed block to its owner.
        #[inline]
        pub fn from_claims(claims: SystemTimerPeripheralsClaims) -> Self {
            let (systimer, systimer_counter) = claims;
            Self {
                systimer: super::systimer::Systimer::new(systimer),
                systimer_counter: super::systimer_counter::SystimerCounter::new(systimer_counter),
            }
        }
    }

    /// The four software interrupt lines: each executor and the radio doorbell owns one. Claimed by the executor's platform handoff.
    pub struct SoftwareInterruptPeripherals {
        pub from_cpu_0: super::from_cpu_0::FromCpu0,
        pub from_cpu_1: super::from_cpu_1::FromCpu1,
        pub from_cpu_2: super::from_cpu_2::FromCpu2,
        pub from_cpu_3: super::from_cpu_3::FromCpu3,
    }

    /// The device registers of [`SoftwareInterruptPeripherals`]'s blocks, which its platform
    /// handoff claims with one `oer_mmio::assume_owned`; the PAC root
    /// does not claim them.
    pub type SoftwareInterruptPeripheralsClaims = (
        super::from_cpu_0::Claim,
        super::from_cpu_1::Claim,
        super::from_cpu_2::Claim,
        super::from_cpu_3::Claim,
    );

    impl SoftwareInterruptPeripherals {
        /// Give each claimed block to its owner.
        #[inline]
        pub fn from_claims(claims: SoftwareInterruptPeripheralsClaims) -> Self {
            let (from_cpu_0, from_cpu_1, from_cpu_2, from_cpu_3) = claims;
            Self {
                from_cpu_0: super::from_cpu_0::FromCpu0::new(from_cpu_0),
                from_cpu_1: super::from_cpu_1::FromCpu1::new(from_cpu_1),
                from_cpu_2: super::from_cpu_2::FromCpu2::new(from_cpu_2),
                from_cpu_3: super::from_cpu_3::FromCpu3::new(from_cpu_3),
            }
        }
    }

    /// The interrupt matrix route and pending words and the CLIC line words, which the interrupt table checks. Claimed by the interrupt table's platform handoff; esp-hal still writes the routes and the lines until the table writes them.
    pub struct InterruptMatrixPeripherals {
        pub clic: super::clic::Clic,
        pub interrupt_core0: super::interrupt_core0::InterruptCore0,
        pub interrupt_core0_status: super::interrupt_core0_status::InterruptCore0Status,
        pub interrupt_core1: super::interrupt_core1::InterruptCore1,
        pub interrupt_core1_status: super::interrupt_core1_status::InterruptCore1Status,
    }

    /// The device registers of [`InterruptMatrixPeripherals`]'s blocks, which its platform
    /// handoff claims with one `oer_mmio::assume_owned`; the PAC root
    /// does not claim them.
    pub type InterruptMatrixPeripheralsClaims = (
        super::clic::Claim,
        super::interrupt_core0::Claim,
        super::interrupt_core0_status::Claim,
        super::interrupt_core1::Claim,
        super::interrupt_core1_status::Claim,
    );

    impl InterruptMatrixPeripherals {
        /// Give each claimed block to its owner.
        #[inline]
        pub fn from_claims(claims: InterruptMatrixPeripheralsClaims) -> Self {
            let (
                clic,
                interrupt_core0,
                interrupt_core0_status,
                interrupt_core1,
                interrupt_core1_status,
            ) = claims;
            Self {
                clic: super::clic::Clic::new(clic),
                interrupt_core0: super::interrupt_core0::InterruptCore0::new(interrupt_core0),
                interrupt_core0_status: super::interrupt_core0_status::InterruptCore0Status::new(
                    interrupt_core0_status,
                ),
                interrupt_core1: super::interrupt_core1::InterruptCore1::new(interrupt_core1),
                interrupt_core1_status: super::interrupt_core1_status::InterruptCore1Status::new(
                    interrupt_core1_status,
                ),
            }
        }
    }

    /// The Wi-Fi MAC receive-interface address pairs, the shared register library's typed block, owned by the Wi-Fi hardware lifecycle with the other Wi-Fi MAC views.
    pub struct WifiMacInterfacePeripherals {
        pub wifi_mac_interface_address: super::wifi_mac_interface_address::WifiMacInterfaceAddress,
    }

    /// IEEE 802.15.4 MAC and source-specific interrupt-route registers owned by the IEEE 802.15.4 hardware lifecycle.
    pub struct Ieee802154Peripherals {
        pub ieee802154_mac: super::ieee802154_mac::Ieee802154Mac,
        pub ieee802154_interrupt_route: super::ieee802154_interrupt_route::Ieee802154InterruptRoute,
    }

    /// Every typed partition.
    pub struct PeripheralPartitions {
        /// The Wi-Fi MAC receive-interface address pairs, the shared register library's typed block, owned by the Wi-Fi hardware lifecycle with the other Wi-Fi MAC views.
        pub wifi_mac_interface: WifiMacInterfacePeripherals,
        /// IEEE 802.15.4 MAC and source-specific interrupt-route registers owned by the IEEE 802.15.4 hardware lifecycle.
        pub ieee802154: Ieee802154Peripherals,
    }

    /// The device registers of every typed block, which the PAC root
    /// takes with one `oer_mmio::assume_owned`.
    pub type Claims = (
        super::wifi_mac_interface_address::Claim,
        super::ieee802154_mac::Claim,
        super::ieee802154_interrupt_route::Claim,
    );

    /// Give each claimed block to its owner in its partition.
    #[inline]
    pub fn partition(claims: Claims) -> PeripheralPartitions {
        let (wifi_mac_interface_address, ieee802154_mac, ieee802154_interrupt_route) = claims;
        PeripheralPartitions {
            wifi_mac_interface: WifiMacInterfacePeripherals {
                wifi_mac_interface_address:
                    super::wifi_mac_interface_address::WifiMacInterfaceAddress::new(
                        wifi_mac_interface_address,
                    ),
            },
            ieee802154: Ieee802154Peripherals {
                ieee802154_mac: super::ieee802154_mac::Ieee802154Mac::new(ieee802154_mac),
                ieee802154_interrupt_route:
                    super::ieee802154_interrupt_route::Ieee802154InterruptRoute::new(
                        ieee802154_interrupt_route,
                    ),
            },
        }
    }
}

